  91:    * @example
  92:   * const needRefresh = getUserState().shouldRefreshToken();
  93:    */
  94:   shouldRefreshToken(): boolean {
  95:     if (!this.auth) {
  96:       return false;
  97:     }
  98:     return this.auth.shouldRefresh();
  99:   }
 100: 
 101:   /**
 102:    * 从网络刷新用户信息
 103:    * @returns {void} 无返回值
 104:    * @example
